IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-019')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-019', N'MI-019', N'Learning Studio/Makerspace Model', N'Develop a model for a learning studio/makerspace that supports experimentation, research, collaboration, and scalable learning innovation.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-020')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-020', N'MI-020', N'CLL Learning & Impact Measures', N'Develop and validate CLL-specific measures for assessing learning, translation, adoption, and longer-term impact.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-021')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-021', N'MI-021', N'Develop approval/governance process for academic programs and digital credentials', N'Develop a workflow that creates a process to consider requests for new programs to ensure new initiatives are aligned with the goals of the college. Move away from individual projects that are reactive to requests.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-022')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-022', N'MI-022', N'Establish and Implement Faculty Governance Process', N'Develop and approve bylaws to provide guidance to the faculty governance system in the college.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-023')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-023', N'MI-023', N'Develop and Implement a Faculty Evaluation and Promotion System', N'In consultation with faculty governance, develop a rubric for faculty evaluation that is aligned with the goals of the college.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-024')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-024', N'MI-024', N'Empower faculty to engage in innovative program development and align work functions', N'Develop an understanding of current faculty workloads and use this information to engage in conversations about time with faculty. This analysis will likely lead toward re-assigning faculty to work on new initiatives aligned with the goals of the college.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-025')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-025', N'MI-025', N'Fill open-rank faculty positions and align faculty work with Strategy 2035', N'Conduct a national search and engage in the search process in a manner that engages faculty as outlined in the Faculty Bylaws.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-026')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-026', N'MI-026', N'Stand up innovative traditional academic programs', N'The goals for this year include submitting for undergraduate and graduate majors in Project Management as well as graduate certificates in Learning.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-027')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-027', N'MI-027', N'Grow the institute-wide faculty network engaged in CLL programs', N'Work with Content and Product Strategy to engage faculty across campus. This will begin by creating a process to consider new programs and continue through identifying faculty across the institute who could contribute toward the goals of the college. This will also include develop a revised payment schedule for faculty engagement that is mutually beneficial to the college and to the faculty. Finally, the products will be developed in a manner that allows for individual pieces of content to be reused and repackaged without additional compensation to faculty for its use. The intellectual property will belong to GT and CLL.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-028')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-028', N'MI-028', N'Recruit students into traditional academic programs', N'Develop a marketing plan to enroll students in the courses and programs offered by the College of Lifetime Learning. This will focus on recruiting students to enroll in the Minor that is jointly offered by the School of Psychology and the College of Lifetime Learning along with the courses focused on Project Management.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
IF NOT EXISTS (SELECT 1 FROM dbo.initiative WHERE initiative_id = N'INI-MI-029')
INSERT INTO dbo.initiative (initiative_id, initiative_code, initiative_name, description, initiative_level, initiative_type, status, source_id) VALUES (N'INI-MI-029', N'MI-029', N'Build coursework as reusable learning experiences', N'Work with Content and Product Strategy to engage faculty in the College of Lifetime Learning and across the Institute to develop content for their courses in a manner that will allow for materials to be used in multiple ways.', 'D-1', 'Initiative', 'Proposed', N'SRC-CLL-REGISTER');
